func (b *Buffer) ReadBytes(n int) []byte {
	src := unsafe.Slice((*byte)(b.mapped), n)
	out := make([]byte, n)
	copy(out, src)
	return out
}

// Handle returns the raw VkBuffer.
func (b *Buffer) Handle() C.VkBuffer { return b.handle }

