// developer's own workstation. The probe stops rather than finds out.
const bankHeadroomFloorGiB = 12

// RunBankHeadroom answers the capacity half of L0b, which is a different
// question from the bandwidth half above: **how much can actually be
// allocated, and does combining the two heaps get past either one?**
//
// It matters because the numbers are close. RADV reports heap 1 (device-local)
// at 83.79 GiB and heap 0 at 41.89 GiB on a machine with 117.7 GiB of GTT, so
// the heaps overlap the same physical memory and their sum is not available.
// UD-Q4_K_XL's resident core is 82.52 GB = 76.9 GiB — 92% of heap 1 — and a
// 262 k KV cache is another 6.4 GB on top. Whether that fits is not something
// the reported heap sizes answer.
//
// Allocation only: no page is written, so this measures what the driver will
// reserve rather than what the machine will hold. Both numbers matter and
// they are not the same number.
func RunBankHeadroom(dev *vk.Device, capGiB int, out io.Writer) error {
	types, err := dev.MemoryTypes()
	if err != nil {
		return err
	}
	// The preferred type first, then the largest host-visible type on the
	// *other* heap, to see whether a second heap extends the first.
	preferred := uint32(0)
	var other uint32 = ^uint32(0)
	for _, t := range types {
		if t.BufferCompatible && t.Has(vk.MemoryDeviceLocal|vk.MemoryHostVisible|vk.MemoryHostCoherent) {
			preferred = t.Index
			break
		}
	}
	preferredHeap := types[preferred].HeapIndex
	for _, t := range types {
		if t.BufferCompatible && t.HeapIndex != preferredHeap && t.Has(vk.MemoryHostVisible) {
			other = t.Index
			break
		}
	}

	fmt.Fprintf(out, "\\nL0b capacity — how much will the device actually reserve?\\n")
	first := probeHeadroom(dev, preferred, capGiB, out)
	fmt.Fprintf(out, "  type %d (heap %d): %.1f GiB\\n", preferred, preferredHeap, first.gib)
	if other != ^uint32(0) {
		second := probeHeadroom(dev, other, capGiB, out)
		fmt.Fprintf(out, "  type %d (heap %d): %.1f GiB\\n", other, types[other].HeapIndex, second.gib)
		both := probeHeadroomBoth(dev, preferred, other, capGiB, out)
		fmt.Fprintf(out, "  both, %d then %d: %.1f GiB (%.1f + %.1f)\\n",
			preferred, other, both.gib, both.firstGiB, both.gib-both.firstGiB)
	}
	return nil
}

type headroomResult struct {
	gib      float64
	firstGiB float64
	stopped  string
}

func probeHeadroom(dev *vk.Device, memType uint32, capGiB int, out io.Writer) headroomResult {
	r, _ := allocUntilFull(dev, memType, capGiB<<30, 0, out)
	return headroomResult{gib: float64(r) / (1 << 30)}
}

// probeHeadroomBoth fills the first type, then keeps going on the second. If
// the heaps are independent the total is the sum; if they overlap the same
// physical memory — which is what a unified-memory APU does — it is not.
func probeHeadroomBoth(dev *vk.Device, a, b uint32, capGiB int, out io.Writer) headroomResult {
	var bufs []*vk.Buffer
	defer func() {
		for _, x := range bufs {
			x.Destroy()
		}
	}()
	first, got := allocUntilFullKeep(dev, a, capGiB<<30, 0, out, &bufs)
	total, _ := allocUntilFullKeep(dev, b, capGiB<<30, got, out, &bufs)
	return headroomResult{gib: float64(got+total) / (1 << 30), firstGiB: float64(first) / (1 << 30)}
}

func allocUntilFull(dev *vk.Device, memType uint32, limit, already int, out io.Writer) (int, string) {
	var bufs []*vk.Buffer
	defer func() {
		for _, x := range bufs {
			x.Destroy()
		}
	}()
	n, why := allocUntilFullKeep(dev, memType, limit, already, out, &bufs)
	return n, why
}

func allocUntilFullKeep(dev *vk.Device, memType uint32, limit, already int, out io.Writer, bufs *[]*vk.Buffer) (int, string) {
	got := 0
	for got+already < limit {
		if avail := memAvailableGiB(); avail > 0 && avail < bankHeadroomFloorGiB {
			return got, fmt.Sprintf("stopped: only %.1f GiB of host memory left", avail)
		}
		b, err := dev.NewBufferOfType(bankBufferBytes, memType)
		if err != nil {
			return got, "allocation refused"
		}
		*bufs = append(*bufs, b)
		got += bankBufferBytes
	}
	return got, "reached the cap"
}

// memAvailableGiB reads MemAvailable, so the probe can stop before it starts
// costing the machine rather than after.
func memAvailableGiB() float64 {
	f, err := os.ReadFile("/proc/meminfo")
	if err != nil {
		return 0
	}
	for _, line := range strings.Split(string(f), "\\n") {
		if !strings.HasPrefix(line, "MemAvailable:") {
			continue
		}
		var kb float64
		if _, err := fmt.Sscanf(line, "MemAvailable: %f kB", &kb); err == nil {
			return kb / (1 << 20)
		}
	}
	return 0
}

