p='cmd/quanterr/main.go'; s=open(p).read()
old = '''	fmt.Printf("  %-10s n=%d min=%.4g max=%.4g rms=%.4g nan=%d inf=%d zero=%d\\n",
		name, len(w), lo, hi, math.Sqrt(sum2/n), nan, inf, zero)
